workoutIndex=nextWorkout();
const homeNumber=value=>Number(value).toLocaleString('es-ES');
const homeDate=date=>new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'short'}).format(new Date(`${date}T12:00:00`));
function homeDays(){return Object.values(data.wearableDays||{}).filter(day=>day&&/^\d{4}-\d{2}-\d{2}$/.test(day.date)).sort((a,b)=>b.date.localeCompare(a.date))}
